"use client";

import { loadVariableFont } from "@remotion/google-fonts/RobotoFlex";
import type React from "react";
import { useEffect, useId, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  DEFAULT_AFTER,
  DEFAULT_BEFORE,
  DEFAULT_WORDS,
  type WidthLockElementId,
  widthLockTimeline,
  wordsOf,
} from "./timeline";

const flex = loadVariableFont("oblique 0deg 10deg", { subsets: ["latin"] });

export interface WidthLockProps {
  before?: string;
  words?: string[];
  after?: string;
  hold?: number;
  accent?: string;
  /** Text color of the fixed lines; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy; needs a variable width axis. Roboto Flex by default. */
  fontFamily?: string;
  /** Weight of the lines (variable "wght" axis). */
  fontWeight?: number;
  /** Size of the text block, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the haze, the fixed lines, single words rising
   * in and single words leaving, by the ids in `./timeline`. Frames on the
   * scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<WidthLockElementId>;
}

const LIMB = ["#e9ecff", "#8a8bff", "#4b2bd6", "#160c3a"] as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    ink: "#F4F3F0",
    hl: (a: string) =>
      `linear-gradient(100deg, ${LIMB[0]} 0%, ${LIMB[1]} 30%, color-mix(in oklab, ${a} 78%, ${LIMB[1]}) 62%, ${LIMB[0]} 100%)`,
    haze: (a: string) =>
      [
        `radial-gradient(64% 52% at 50% 122%, color-mix(in oklab, ${LIMB[2]} 46%, transparent) 0%, color-mix(in oklab, ${LIMB[3]} 50%, transparent) 50%, transparent 80%)`,
        `radial-gradient(30% 22% at 50% 106%, color-mix(in oklab, ${a} 24%, transparent) 0%, transparent 80%)`,
      ].join(", "),
    grain: 0.05,
  },
  light: {
    bg: "#F5F4F0",
    ink: "#111113",
    hl: (a: string) =>
      `linear-gradient(100deg, ${LIMB[3]} 0%, ${LIMB[2]} 34%, ${a} 64%, ${LIMB[3]} 100%)`,
    haze: (a: string) =>
      `radial-gradient(60% 48% at 50% 120%, color-mix(in oklab, ${LIMB[1]} 34%, transparent) 0%, color-mix(in oklab, ${a} 8%, transparent) 50%, transparent 80%)`,
    grain: 0.035,
  },
} as const;

const WDTH_MIN = 25;
const WDTH_MAX = 151;
const SAMPLES = [25, 35, 50, 65, 80, 100, 115, 130, 151];
const WGHT = 480;
const TRACK = -0.02;
const MAX_EXTRA_TRACK = 0.04;
const LONGEST_AT = 46;
const LINE = 0.98;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.85, 0.35);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const LOCK_SPRING = { damping: 13, stiffness: 120, mass: 0.9 };

const fvs = (wdth: number, wght: number) =>
  `"wdth" ${wdth.toFixed(2)}, "wght" ${wght}, "slnt" 0, "opsz" 72`;

type Curve = number[];

function widthAt(curve: Curve, wdth: number) {
  const w = Math.min(WDTH_MAX, Math.max(WDTH_MIN, wdth));
  for (let i = 0; i < SAMPLES.length - 1; i++) {
    if (w <= SAMPLES[i + 1]) {
      const k = (w - SAMPLES[i]) / (SAMPLES[i + 1] - SAMPLES[i]);
      return curve[i] + (curve[i + 1] - curve[i]) * k;
    }
  }
  return curve[curve.length - 1];
}

function solveWdth(curve: Curve, target: number) {
  if (target <= curve[0]) return WDTH_MIN;
  for (let i = 0; i < SAMPLES.length - 1; i++) {
    if (target <= curve[i + 1]) {
      const k = (target - curve[i]) / Math.max(1e-6, curve[i + 1] - curve[i]);
      return SAMPLES[i] + (SAMPLES[i + 1] - SAMPLES[i]) * k;
    }
  }
  return WDTH_MAX;
}

function measure(
  strings: string[],
  fontFamily: string,
  fontWeight: number,
): Curve[] {
  const probe = document.createElement("span");
  Object.assign(probe.style, {
    position: "absolute",
    left: "-99999px",
    top: "0",
    visibility: "hidden",
    whiteSpace: "pre",
    fontFamily: `"${fontFamily}"`,
    fontStyle: "normal",
    fontSize: "100px",
    lineHeight: "1",
    letterSpacing: `${TRACK}em`,
  });
  document.body.appendChild(probe);
  const curves = strings.map((s) =>
    SAMPLES.map((wd) => {
      probe.style.fontVariationSettings = fvs(wd, fontWeight);
      probe.textContent = s;
      return probe.getBoundingClientRect().width / 100 - TRACK;
    }),
  );
  probe.remove();
  return curves;
}

function useCurves(strings: string[], fontFamily: string, fontWeight: number) {
  const key = strings.join("\u0001");
  const font = `${fontWeight}\u0002${fontFamily}`;
  const [state, setState] = useState<{
    key: string;
    font: string;
    c: Curve[];
  } | null>(null);
  const [handle] = useState(() => delayRender("width-lock: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      flex.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          font,
          c: measure(key.split("\u0001"), fontFamily, fontWeight),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, font, fontFamily, fontWeight]);
  return state && state.key === key && state.font === font ? state.c : null;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `wl${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={5}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Fit {
  wdth: number;
  extra: number;
}

const NATURAL: Fit = { wdth: 100, extra: 0 };

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function WidthLock(props: WidthLockProps) {
  const {
    before = DEFAULT_BEFORE,
    words = DEFAULT_WORDS,
    after = DEFAULT_AFTER,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = flex.fontFamily,
    fontWeight = WGHT,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    widthLockTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const list = wordsOf(words);
  const strings = useMemo(
    () => [before, after, ...list].map((s) => s || " "),
    [before, after, list],
  );
  const curves = useCurves(strings, fontFamily, fontWeight);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!curves) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const measureW = W * (portrait ? 0.86 : 0.74);
  const rows = (before ? 1 : 0) + 1 + (after ? 1 : 0);

  const live = strings
    .map((s, i) => ({ s, curve: curves[i] }))
    .filter((r) => r.s.trim());
  const floor = Math.max(...live.map((r) => r.curve[0]));
  const ceil = Math.min(...live.map((r) => r.curve[r.curve.length - 1]));
  const pref = Math.max(...live.map((r) => widthAt(r.curve, LONGEST_AT)));
  const M =
    ceil >= floor
      ? Math.min(ceil, Math.max(floor, pref))
      : Math.max(floor, 0.1);
  const F = Math.min(
    measureW / M,
    (H * (portrait ? 0.5 : 0.72)) / (rows * LINE),
  );

  const fit = (i: number): Fit => {
    const curve = curves[i];
    const wdth = solveWdth(curve, M);
    const n = Math.max(1, Array.from(strings[i]).length - 1);
    const short = M - widthAt(curve, wdth);
    return {
      wdth,
      extra: short > 0.001 ? Math.min(MAX_EXTRA_TRACK, short / n) : 0,
    };
  };

  const lineH = F * LINE;
  const blockH = rows * lineH;
  const top = H / 2 - blockH / 2 - F * 0.02;
  const cx = W / 2;

  const renderRun = (
    i: number,
    state: Fit,
    key: string,
    style: React.CSSProperties,
    gradient: boolean,
  ) => {
    const s = strings[i];
    const n = Math.max(1, Array.from(s).length - 1);
    const w = (widthAt(curves[i], state.wdth) + state.extra * n) * F;
    return (
      <div
        key={key}
        style={{
          position: "absolute",
          left: cx - w / 2,
          top: 0,
          height: lineH * 1.24,
          lineHeight: `${lineH * 1.24}px`,
          whiteSpace: "pre",
          fontFamily,
          fontStyle: "normal",
          fontSize: F,
          fontVariationSettings: fvs(state.wdth, fontWeight),
          letterSpacing: `${TRACK + state.extra}em`,
          color: fg,
          ...(gradient
            ? {
                backgroundImage: c.hl(accent),
                backgroundSize: `${Math.max(w, 1)}px 100%`,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }
            : null),
          ...style,
        }}
      >
        {s}
      </div>
    );
  };

  const lerpFit = (a: Fit, b: Fit, k: number): Fit => ({
    wdth: a.wdth + (b.wdth - a.wdth) * k,
    extra: Math.max(0, a.extra + (b.extra - a.extra) * k),
  });

  const lock = (el: ResolvedElement<WidthLockElementId>) =>
    spring({
      frame: t - (el.start + el.beat("lock")),
      fps,
      config: LOCK_SPRING,
    });

  const riseY = (el: ResolvedElement<WidthLockElementId>) => {
    const p = interpolate(t, [el.start, el.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    return {
      y: (1 - p) * lineH * 0.34,
      o: p,
      blur: (1 - p) * F * 0.05,
      tilt: glide(midway(p)),
    };
  };

  const band = (row: number, children: React.ReactNode, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        width: W,
        top: top + row * lineH - lineH * 0.12,
        height: lineH * 1.24,
      }}
    >
      {children}
    </div>
  );

  const bands: React.ReactNode[] = [];
  let row = 0;

  const fixed = (idx: number, el: ResolvedElement<WidthLockElementId>) => {
    const r = riseY(el);
    const state = lerpFit(NATURAL, fit(idx), lock(el));
    bands.push(
      band(
        row,
        renderRun(
          idx,
          state,
          `f${idx}`,
          {
            transform: `translateY(${r.y.toFixed(2)}px)${r.tilt}`,
            opacity: r.o,
            filter: r.blur > 0.05 ? `blur(${r.blur.toFixed(2)}px)` : undefined,
          },
          false,
        ),
        `band${row}`,
      ),
    );
    row++;
  };

  if (before) fixed(0, tl.get("before"));

  {
    const runs: React.ReactNode[] = [];
    list.forEach((_, k) => {
      const idx = 2 + k;
      const wordEl = tl.get(`word:${k}`);
      const leaveEl = k < list.length - 1 ? tl.get(`leave:${k}`) : null;
      if (t < wordEl.start - 1) return;
      if (leaveEl !== null && t > leaveEl.end + 1) return;
      const r = riseY(wordEl);
      const state = lerpFit(NATURAL, fit(idx), lock(wordEl));
      let o = r.o;
      let blur = r.blur;
      let sx = 1;
      if (leaveEl !== null) {
        const p = interpolate(t, [leaveEl.start, leaveEl.end], [0, 1], {
          ...CLAMP,
          easing: EASE_IN,
        });
        sx = 1 - p * 0.94;
        o *= 1 - p;
        blur += p * F * 0.03;
      }
      runs.push(
        renderRun(
          idx,
          state,
          `w${k}`,
          {
            transform: `translateY(${r.y.toFixed(2)}px) scaleX(${sx.toFixed(4)})${r.tilt}`,
            opacity: o,
            filter: blur > 0.05 ? `blur(${blur.toFixed(2)}px)` : undefined,
          },
          true,
        ),
      );
    });
    bands.push(band(row, runs, `band${row}`));
    row++;
  }

  if (after) fixed(1, tl.get("after"));

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {transparent ? null : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: c.haze(accent),
            opacity: interpolate(
              t,
              [tl.get("haze").start, tl.get("haze").end],
              [0.4, 1],
              CLAMP,
            ),
          }}
        />
      )}
      <ScaleLayer scale={scale}>{bands}</ScaleLayer>
      {transparent || !grain ? null : <Grain opacity={c.grain} />}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The haze lifting, the fixed lines and the first word rising and locking to
// one width on a spring, then each next word swapping in: the word before
// squeezes out and the new one rises and locks. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type WidthLockElementId =
  | "haze"
  | "before"
  | `word:${number}`
  | "after"
  | `leave:${number}`;

export interface WidthLockTimingProps {
  before?: string;
  words?: string[];
  after?: string;
  hold?: number;
}

export const DEFAULT_BEFORE = "Ship the";
export const DEFAULT_WORDS = [
  "trailer",
  "transitions",
  "captions",
  "launch video",
];
export const DEFAULT_AFTER = "by tonight.";

const HAZE = 30;
const RISE = 18;
const FIRST_AT = 3;
const AFTER_AT = 6;
const LOCK_AT = 18;
/** Each row locks this much later than the row above. */
const ROW_LAG = 3;
const FIRST_SWAP = 46;
const MIN_STEP = 16;
const OUT = 7;
const IN_AT = 6;
const IN = 10;
const SWAP_LOCK = 13;

/** The swapping words: the given ones, or a single default when empty. */
export function wordsOf(words: string[]) {
  return words.length > 0 ? words : ["launch video"];
}

// `haze` lifts the background glow. `before`, `word:0` and `after` rise over
// their length and lock to the shared width from their `lock` beat, each row
// a little later. `leave:<k>` squeezes word `k` out; `word:<k>` (from 1)
// rises in after it and locks from its `lock` beat. Leaves and words form a
// chain, each following the one before.
export const widthLockTimeline = defineTimeline<
  WidthLockElementId,
  WidthLockTimingProps
>(
  ({
    before = DEFAULT_BEFORE,
    words = DEFAULT_WORDS,
    after = DEFAULT_AFTER,
    hold = 30,
  }) => {
    const list = wordsOf(words);
    const STEP = Math.max(MIN_STEP, hold);
    const swapAt = (k: number) => FIRST_SWAP + (k - 1) * STEP;
    const wordRow = before ? 1 : 0;
    const elements: TimelineElement<WidthLockElementId>[] = [
      { id: "haze", lane: "Haze", label: "haze", start: 0, length: HAZE },
    ];
    if (before) {
      elements.push({
        id: "before",
        lane: "Before",
        label: before,
        start: 0,
        length: RISE,
        beats: { lock: LOCK_AT },
      });
    }
    list.forEach((w, k) => {
      if (k > 0) {
        elements.push({
          id: `leave:${k - 1}`,
          lane: "Words",
          label: `${list[k - 1]} out`,
          start: swapAt(k),
          length: OUT,
          follows: `word:${k - 1}`,
        });
      }
      const enterAt = k === 0 ? FIRST_AT : swapAt(k) + IN_AT;
      const lockAt =
        k === 0 ? LOCK_AT + wordRow * ROW_LAG : swapAt(k) + SWAP_LOCK;
      elements.push({
        id: `word:${k}`,
        lane: "Words",
        label: w,
        start: enterAt,
        length: k === 0 ? RISE : IN,
        follows: k > 0 ? `leave:${k - 1}` : undefined,
        beats: { lock: lockAt - enterAt },
      });
    });
    if (after) {
      elements.push({
        id: "after",
        lane: "After",
        label: after,
        start: AFTER_AT,
        length: RISE,
        beats: { lock: LOCK_AT + (wordRow + 1) * ROW_LAG - AFTER_AT },
      });
    }
    return elements.sort((a, b) => a.start - b.start);
  },
);
